namespace mlash {
WebDavClient::WebDavClient(QObject* parent,QUrl fixture):QObject(parent),fixture_(std::move(fixture)) { deadline_.setSingleShot(true); connect(&deadline_,&QTimer::timeout,this,[this] { complete(Result::fail("WebDAV操作超过120秒总预算")); }); }
WebDavClient::~WebDavClient() { ++generation_; if (lookup_>=0) QHostInfo::abortHostLookup(lookup_); if (reply_) reply_->abort(); }
void WebDavClient::complete(Result result,QByteArray bytes) { if (!busy_) return; ++generation_; deadline_.stop(); if (resolveTimer_) { resolveTimer_->stop(); resolveTimer_->deleteLater(); resolveTimer_=nullptr; } if (lookup_>=0) QHostInfo::abortHostLookup(lookup_); lookup_=-1; const auto reply=reply_; reply_=nullptr; if (reply) reply->abort(); busy_=false; config_={}; response_.clear(); auto done=std::move(done_); if (done) done(result,std::move(bytes)); }
void WebDavClient::hashBytes(QByteArray bytes,std::function<void(QByteArray)> done) { hashPending_=true; const auto token=generation_; runTask(this,[bytes=std::move(bytes)] { return QCryptographicHash::hash(bytes,QCryptographicHash::Sha256); },[this,token,done=std::move(done)](QByteArray hash) mutable { hashPending_=false; if (token==generation_&&busy_) done(std::move(hash)); }); }
void WebDavClient::cancel() { complete({false,"远端操作已取消",{{"cancelled",true}}}); }
void WebDavClient::start(const QJsonObject& config,int port,Done done,std::function<void()> resolved) {
    if (busy_||hashPending_) { done(Result::fail("已有WebDAV操作正在进行"),{}); return; } const auto valid=validateRemoteBackup(config); if (!valid.ok||config.isEmpty()||(config.value("route").toString("direct")=="core"&&(port<1024||port>65535))) { done(valid.ok?Result::fail("请先配置WebDAV连接和备份密码"):valid,{}); return; }
    busy_=true; done_=std::move(done); config_=config; root_=QUrl(config.value("url").toString()); transport_=fixture_.isEmpty()?root_:fixture_; QNetworkProxy proxy=config.value("route").toString("direct")=="core"?QNetworkProxy(QNetworkProxy::HttpProxy,"127.0.0.1",quint16(port)):QNetworkProxy(QNetworkProxy::NoProxy); if (proxy.type()==QNetworkProxy::HttpProxy) proxy.setCapabilities(QNetworkProxy::TunnelingCapability); network_.setProxy(proxy); const auto token=++generation_; deadline_.start(120000);
    const auto deliver=[this,token,resolved=std::move(resolved)](const QList<QHostAddress>& addresses) mutable { if (token!=generation_||!busy_) return; if (addresses.isEmpty()) { complete(Result::fail("WebDAV主机解析失败")); return; } for (const auto& address:addresses) if (address.isNull()||address.isMulticast()||address==QHostAddress::AnyIPv4||address==QHostAddress::AnyIPv6||address==QHostAddress::Broadcast||(fixture_.isEmpty()&&!config_.value("allow_private").toBool()&&!SubscriptionDownloader::publicAddress(address))) { complete(Result::fail("WebDAV目标为受限地址；本地网络服务器需显式允许")); return; } address_=addresses.first(); resolved(); };
    QHostAddress literal; if (literal.setAddress(transport_.host())) { auto callback=deliver; callback({literal}); return; } auto shared=std::make_shared<std::function<void(const QList<QHostAddress>&)>>(deliver); auto* timer=new QTimer(this); resolveTimer_=timer; timer->setSingleShot(true); lookup_=QHostInfo::lookupHost(transport_.host(),this,[this,token,timer,shared](const QHostInfo& info) { timer->stop(); timer->deleteLater(); if (token!=generation_) return; lookup_=-1; auto callback=std::move(*shared); if (callback) callback(info.error()==QHostInfo::NoError?info.addresses():QList<QHostAddress>{}); }); connect(timer,&QTimer::timeout,this,[this,token,timer,shared] { timer->deleteLater(); if (token!=generation_) return; if (lookup_>=0) QHostInfo::abortHostLookup(lookup_); lookup_=-1; auto callback=std::move(*shared); if (callback) callback({}); }); timer->start(10000);
}
void WebDavClient::send(const QByteArray& method,const QString& file,const QByteArray& body,const QString& destination,qint64 limit,Done done) {
    if (!busy_) return; const auto safe=[](const QString& name) { if (name.isEmpty()) return true; for (const auto ch:name) if (!(ch.isLetterOrNumber()&&ch.unicode()<128)&&ch!='.'&&ch!='_'&&ch!='-') return false; return name.size()<=160&&!name.contains(".."); }; if (!safe(file)||!safe(destination)) { complete(Result::fail("WebDAV文件名无效")); return; }
    QUrl url=transport_; url.setPath(url.path()+file); url.setHost(address_.toString()); QNetworkRequest request(url); QString authority=root_.host(); if (authority.contains(':')) authority='['+authority+']'; if (root_.port()!=-1) authority+=':'+QString::number(root_.port()); request.setRawHeader("Host",authority.toUtf8()); request.setPeerVerifyName(root_.host()); request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::ManualRedirectPolicy); request.setTransferTimeout(15000);
    if (!config_.value("username").toString().isEmpty()) request.setRawHeader("Authorization","Basic "+(config_.value("username").toString()+':'+config_.value("password").toString()).toUtf8().toBase64()); request.setRawHeader("Content-Type",method=="PROPFIND"?"application/xml; charset=utf-8":"application/octet-stream"); if (method=="PROPFIND") request.setRawHeader("Depth","1"); if (method=="PUT") request.setRawHeader("If-None-Match","*"); if (method=="MOVE") { auto target=root_; target.setPath(target.path()+destination); request.setRawHeader("Destination",target.toEncoded()); request.setRawHeader("Overwrite","F"); }
    response_.clear(); auto* reply=network_.sendCustomRequest(request,method,body); reply_=reply; reply->setReadBufferSize(64*1024); const auto token=generation_;
    const auto collect=[this,reply,token,limit] { if (token!=generation_||reply_!=reply) return; response_+=reply->read(qMax(qint64(1),limit+1-response_.size())); if (response_.size()>limit) complete(Result::fail("WebDAV响应超过大小限制")); }; connect(reply,&QNetworkReply::readyRead,this,collect);
    connect(reply,&QNetworkReply::finished,this,[this,reply,token,method,collect,done=std::move(done)]() mutable { if (token!=generation_||reply_!=reply) { reply->deleteLater(); return; } collect(); if (token!=generation_||reply_!=reply) { reply->deleteLater(); return; } reply_=nullptr; const int status=reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt(); const auto bytes=std::move(response_); const bool ok=reply->error()==QNetworkReply::NoError&&(method=="PROPFIND"?status==207:method=="MOVE"?status==201:method=="GET"?status==200:status==201||status==204); reply->deleteLater(); if (!ok) { complete(Result::fail(status?QString("WebDAV HTTP %1；未跟随重定向或回退路径").arg(status):QString("WebDAV连接/TLS校验失败"))); return; } done({true,{},{{"http_status",status}}},bytes); });
}
void WebDavClient::list(const QJsonObject& config,int port,Done done) { start(config,port,std::move(done),[this] { send("PROPFIND",{},"<?xml version=\"1.0\"?><d:propfind xmlns:d=\"DAV:\"><d:prop><d:getcontentlength/><d:getlastmodified/></d:prop></d:propfind>",{},1024*1024,[this](Result,QByteArray xml) { hashPending_=true; const auto token=generation_; const auto root=root_; runTask(this,[root,xml=std::move(xml)] { return parseListing(root,xml); },[this,token](Result result) { hashPending_=false; if (token==generation_&&busy_) complete(result); }); }); }); }
void WebDavClient::download(const QJsonObject& config,int port,const QString& file,Done done) { if (!remoteBackupFileName(file)) { done(Result::fail("请选择目录中的有效Mlash备份文件"),{}); return; } start(config,port,std::move(done),[this,file] { send("GET",file,{}, {},64*1024*1024+64,[this](Result result,QByteArray bytes) { complete(result,std::move(bytes)); }); }); }
void WebDavClient::upload(const QJsonObject& config,int port,const QString& name,const QByteArray& bytes,Done done) {
    if (!remoteBackupFileName(name)||bytes.isEmpty()||bytes.size()>64*1024*1024+64) { done(Result::fail("上传备份名称或大小无效"),{}); return; } const auto temporary=".mlash-upload-"+QUuid::createUuid().toString(QUuid::WithoutBraces)+".tmp";
    start(config,port,std::move(done),[this,temporary,name,bytes] { hashBytes(bytes,[this,temporary,name,bytes](QByteArray digest) { send("PUT",temporary,bytes,{},4096,[this,temporary,name,digest](Result,QByteArray) { send("GET",temporary,{}, {},64*1024*1024+64,[this,temporary,name,digest](Result,QByteArray observed) {
        hashBytes(std::move(observed),[this,temporary,name,digest](QByteArray observedHash) { if (observedHash!=digest) { complete(Result::fail("WebDAV临时备份回读哈希不一致，旧远端版本保持")); return; } send("MOVE",temporary,{},name,4096,[this,name,digest](Result,QByteArray) { send("GET",name,{}, {},64*1024*1024+64,[this,name,digest](Result,QByteArray final) {
            hashBytes(std::move(final),[this,name,digest](QByteArray finalHash) { if (finalHash!=digest) { complete(Result::fail("WebDAV最终备份回读哈希不一致")); return; } complete({true,{},{{"file",name},{"sha256",QString::fromLatin1(digest.toHex())}}}); });
        }); }); });
    }); }); }); });
}
Result WebDavClient::parseListing(const QUrl& root,const QByteArray& xml) {
    if (xml.size()>1024*1024) return Result::fail("WebDAV目录响应超过1MiB"); QXmlStreamReader reader(xml); QJsonArray files; QSet<QString> names; int depth=0,count=0; bool response=false,multistatus=false,propertyOk=false; QString href,modified; qint64 size=-1;
    while (!reader.atEnd()) { const auto token=reader.readNext(); if (++count>10000||token==QXmlStreamReader::DTD||token==QXmlStreamReader::EntityReference) return Result::fail("WebDAV目录XML结构不受支持"); if (reader.isStartElement()) { if (++depth>16) return Result::fail("WebDAV目录XML超过深度限制"); const auto name=reader.name().toString(); const bool dav=reader.namespaceUri()=="DAV:"; if (depth==1) multistatus=dav&&name=="multistatus"; if (dav&&name=="response") { if (response) return Result::fail("WebDAV目录响应嵌套无效"); response=true; propertyOk=false; href.clear(); modified.clear(); size=-1; } else if (response&&dav&&QStringList{"href","getcontentlength","getlastmodified","status"}.contains(name)) { const auto value=reader.readElementText(); --depth; if (value.size()>4096) return Result::fail("WebDAV目录字段超过限制"); if (name=="status") propertyOk=propertyOk||value.startsWith("HTTP/1.1 200 ")||value.startsWith("HTTP/1.0 200 "); else if (name=="href") href=value; else if (name=="getlastmodified") modified=value.left(128); else { bool valid=false; size=value.toLongLong(&valid); if (!valid) size=-1; } } }
        else if (reader.isEndElement()) { if (reader.namespaceUri()=="DAV:"&&reader.name()=="response") { response=false; const auto url=root.resolved(QUrl(href,QUrl::StrictMode)); const auto prefix=root.path(); const auto path=url.path(); const auto name=path.mid(prefix.size()); if (propertyOk&&url.scheme()==root.scheme()&&url.host()==root.host()&&url.port()==root.port()&&url.userInfo().isEmpty()&&!url.hasQuery()&&!url.hasFragment()&&path.startsWith(prefix)&&remoteBackupFileName(name)&&!names.contains(name)&&size>=0&&size<=64*1024*1024+64) { if (files.size()>=200) return Result::fail("WebDAV目录超过200份备份，请缩小配置目录"); names.insert(name); files.append(QJsonObject{{"name",name},{"bytes",double(size)},{"modified",modified}}); } } --depth; }
    } if (reader.hasError()||!multistatus) return Result::fail("WebDAV目录不是有效DAV multistatus文档"); return {true,{},{{"files",files}}};
}
}
